    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: Which ASA Physical Status classification describes a patient with severe systemic disease that is a constant threat to life?', '["ASA I", "ASA II", "ASA III", "ASA IV"]', 3, 'ASA IV patients have severe disease that is life-threatening. (Schwartz''s Ch. 11)'),
    (v_topic_id, '2: According to the Revised Cardiac Risk Index (RCRI), which of the following is NOT a risk factor for major cardiac complications?', '["Diabetes requiring insulin", "History of ischemic heart disease", "Hypertension", "Renal insufficiency (Cr > 2.0)"]', 2, 'HTN alone is not an RCRI independent predictor. (de Virgilio Ch. 1)'),
    (v_topic_id, '3: How many weeks should a patient ideally stop smoking before surgery to significantly reduce postoperative pulmonary complications?', '["1 week", "2 weeks", "4 weeks", "8 weeks"]', 3, 'At least 8 weeks are needed to improve ciliary function and decrease sputum. (Mont Reid Ch. 1)'),
    (v_topic_id, '4: In a patient with a recent Myocardial Infarction, what is the minimum recommended wait time before elective non-cardiac surgery?', '["1 month", "3 months", "6 months", "1 year"]', 2, 'Risk of re-infarction is significantly higher before 6 months. (Schwartz''s Ch. 11)'),
    (v_topic_id, '5: Which preoperative test is the most useful predictor of postoperative pulmonary complications in patients undergoing lung resection?', '["Chest X-ray", "Pulse oximetry", "FEV1 and DLCO", "Peak flow"]', 2, 'Forced Expiratory Volume in 1 second is critical for risk stratification. (de Virgilio Ch. 1)'),
    (v_topic_id, '6: "Mallampati Classification" is used to assess the difficulty of:', '["Surgical incision", "Endotracheal intubation", "Wound healing", "None"]', 1, 'Assesses the visibility of the soft palate and uvula. (Mont Reid Ch. 1)'),
    (v_topic_id, '7: Which medication should typically be CONTINUED on the morning of surgery?', '["ACE Inhibitors", "Warfarin", "Beta-blockers", "Metformin"]', 2, 'Beta-blockers are continued to prevent withdrawal tachycardia/ischemia. (Schwartz''s Ch. 11)'),
    (v_topic_id, '8: Patients with severe COPD should receive which preoperative intervention to improve outcomes?', '["Prophylactic antibiotics", "Aggressive incentive spirometry and bronchodilators", "Bed rest", "None"]', 1, 'Optimization of lung function is key. (de Virgilio Ch. 1)'),
    (v_topic_id, '9: "Child-Pugh Score" is used to assess the surgical risk in patients with:', '["Heart failure", "Liver cirrhosis", "Renal failure", "COPD"]', 1, 'Uses bilirubin, albumin, INR, ascites, and encephalopathy. (Mont Reid Ch. 1)'),
    (v_topic_id, '10: A Child-Pugh Class C patient carries an approximate operative mortality of:', '["5%", "15%", "50%", "80%"]', 3, 'High-risk category; elective surgery is usually contraindicated. (Schwartz''s Ch. 11)'),
    (v_topic_id, '11: Which electrolyte abnormality is most dangerous to leave uncorrected before surgery?', '["Mild Hyponatremia", "Hypokalemia (especially if on Digoxin)", "Hypermagnesemia", "None"]', 1, 'Predisposes to cardiac arrhythmias during anesthesia. (de Virgilio Ch. 1)'),
    (v_topic_id, '12: What is the "NPO after midnight" rule primarily intended to prevent?', '["Dehydration", "Aspiration of gastric contents", "Hypoglycemia", "Infection"]', 1, 'Protects the airway during induction. (Mont Reid Ch. 1)'),
    (v_topic_id, '13: In the preoperative setting, "Informed Consent" must include risks, benefits, and:', '["Cost", "Alternatives", "Surgeon''s hobbies", "None"]', 1, 'Patient must understand the other options available. (Schwartz''s Ch. 11)'),
    (v_topic_id, '14: Which of the following is a marker of "severe" malnutrition (Albumin level)?', '["< 4.5 g/dL", "< 3.5 g/dL", "< 2.8 g/dL", "< 5.0 g/dL"]', 2, 'Low albumin is a strong predictor of poor wound healing. (de Virgilio Ch. 1)'),
    (v_topic_id, '15: "Bridge therapy" with Heparin in a patient on Warfarin is typically started when the INR falls below:', '["3.0", "2.0", "1.5", "1.0"]', 1, 'Provides coverage as the effect of Warfarin wears off. (Mont Reid Ch. 1)'),
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: In the "TNM" staging system for cancer, "T" stands for:', '["Time", "Tumor (size or depth)", "Total", "None"]', 1, 'Describes the local extent of the primary tumor. (Schwartz''s Ch. 10)'),
    (v_topic_id, '102: "N" in TNM stands for:', '["Nerves", "Regional Lymph Nodes", "Nutrition", "None"]', 1, 'Assesses the involvement of regional nodes. (de Virgilio Ch. 3)'),
    (v_topic_id, '103: "M" in TNM stands for:', '["Muscle", "Distant Metastasis", "Margins", "None"]', 1, 'Indicates if the cancer has spread to distant organs. (Mont Reid Ch. 13)'),
    (v_topic_id, '104: A "Positive Margin" after surgical resection means:', '["The cancer is cured", "Tumor cells reach the edge of the specimen", "The specimen is heavy", "None"]', 1, 'Increases risk of local recurrence. (Schwartz''s Ch. 10)'),
    (v_topic_id, '105: "Sentinel Lymph Node Biopsy" (SLNB) is based on the theory that:', E'["Cancer spreads randomly", "Cancer spreads first to a specific \\"gateway\\" node", "All nodes are equal", "None"]', 1, 'Standard in breast cancer and melanoma. (de Virgilio Ch. 3)'),
    (v_topic_id, '106: "Fine Needle Aspiration" (FNA) provides:', '["Tissue architecture", "Cytology (individual cells)", "Large specimen", "None"]', 1, 'Cannot distinguish invasive from in-situ in some cancers. (Mont Reid Ch. 13)'),
    (v_topic_id, '107: "Core Needle Biopsy" differs from FNA because it provides:', '["Cells only", "Tissue architecture", "Fluid only", "None"]', 1, 'Allows for histological assessment. (Schwartz''s Ch. 10)'),
    (v_topic_id, '108: "Incisional Biopsy" involves:', '["Removing the entire tumor", "Removing a small piece of a large tumor", "Removing only skin", "None"]', 1, 'Used when total excision is impractical or dangerous. (de Virgilio Ch. 3)'),
    (v_topic_id, '109: "Adjuvant Therapy" refers to treatment given:', '["Before surgery", "After surgery", "Instead of surgery", "None"]', 1, 'Intended to kill micrometastases. (Mont Reid Ch. 13)'),
    (v_topic_id, '110: "Neoadjuvant Therapy" refers to treatment given:', '["Before surgery", "After surgery", "During surgery", "None"]', 0, 'Often used to shrink tumors for better resectability. (Schwartz''s Ch. 10)'),
    (v_topic_id, '111: "Palliative Surgery" is performed to:', '["Cure the cancer", "Relieve symptoms (e.g., obstruction, pain)", "Diagnose", "None"]', 1, 'Focus is on quality of life. (de Virgilio Ch. 3)'),
    (v_topic_id, '112: Which post-op day (POD) does "Atelectasis" typically cause fever?', '["POD 1-2", "POD 3-5", "POD 5-7", "None"]', 0, '"Wind" - the first of the 5 Ws. (Mont Reid Ch. 1)'),
    (v_topic_id, '113: "Urinary Tract Infection" (UTI) typically causes post-op fever on:', '["POD 1", "POD 3", "POD 5", "None"]', 1, '"Water" - usually related to catheterization. (Schwartz''s Ch. 11)'),
    (v_topic_id, '114: "DVT and PE" are common causes of post-op fever on:', '["POD 1", "POD 3", "POD 5+", "None"]', 2, '"Walking" - prophylaxis is critical. (de Virgilio Ch. 1)'),
    (v_topic_id, '115: "Wound Infection" typically manifests as fever on:', '["POD 1", "POD 5-7", "POD 14", "None"]', 1, '"Wound" - check the incision. (Mont Reid Ch. 1)'),
    (v_topic_id, '116: What is the most common cause of "Immediate" postoperative fever (within hours)?', '["Pneumonia", "Malignant Hyperthermia or Transfusion Reaction", "Wound infection", "None"]', 1, 'Also pre-existing infection. (Schwartz''s Ch. 11)'),
    (v_topic_id, '117: A "Post-op Ileus" is normal for how many days after abdominal surgery?', '["1 day", "3-5 days", "10 days", "None"]', 1, 'Return of function: Small bowel -> Stomach -> Colon. (de Virgilio Ch. 1)'),
    (v_topic_id, '118: "Ogilvie Syndrome" refers to acute pseudo-obstruction of the:', '["Esophagus", "Small bowel", "Colon (especially cecum)", "None"]', 2, 'Common in elderly/bedridden; risk of perforation. (Mont Reid Ch. 2)'),
    (v_topic_id, '119: What is the most common cause of "Mechanical" small bowel obstruction in a patient with prior surgery?', '["Cancer", "Adhesions", "Hernia", "Crohn''s"]', 1, 'Internal scarring. (Schwartz''s Ch. 28)'),
    (v_topic_id, '120: "Wound Dehiscence" is most common on which post-op day?', '["POD 1", "POD 5-8", "POD 30", "None"]', 1, 'Often preceded by serosanguinous discharge. (de Virgilio Ch. 7)'),
    (v_topic_id, '121: "Evisceration" is a surgical emergency where:', '["The skin opens", "Abdominal contents (bowel) protrude through the wound", "An abscess forms", "None"]', 1, 'Requires immediate sterile coverage and return to OR. (Mont Reid Ch. 1)'),
    (v_topic_id, '122: What is the most common cause of "Post-op Urinary Retention"?', '["Kidney failure", "Increased sympathetic tone and pain", "UTI", "None"]', 1, 'Reflex inhibition of the detrusor muscle. (Schwartz''s Ch. 11)'),
    (v_topic_id, '123: Which scale is used to assess "DVT risk" and guide prophylaxis?', '["Caprini Score", "GCS", "Apgar", "None"]', 0, 'Factors include age, surgery type, and mobility. (de Virgilio Ch. 1)'),
    (v_topic_id, '124: "Virchow''s Triad" for thrombosis includes Stasis, Endothelial Injury, and:', '["Anemia", "Hypercoagulability", "Hypotension", "None"]', 1, 'Key to understanding DVT pathophysiology. (Mont Reid Ch. 4)'),
    (v_topic_id, '125: What is the gold standard for diagnosing a "Pulmonary Embolism"?', '["Chest X-ray", "CT Angiography (CTPA)", "D-dimer", "ECG"]', 1, 'Provides direct visualization of the clot. (Schwartz''s Ch. 11)'),
    (v_topic_id, '126: "Absorption" sutures lose their tensile strength within ____ days.', '["10", "60", "365", "None"]', 1, 'e.g., Vicryl, Monocryl, PDS. (de Virgilio Ch. 7)'),
    (v_topic_id, '127: "Silk" is a natural suture material that is technically:', '["Absorbable", "Non-absorbable (but degrades over years)", "Metal", "None"]', 1, 'Braided; has high knot security but more tissue reaction. (Mont Reid Ch. 1)'),
    (v_topic_id, '128: Which suture is preferred for "skin closure" in an area of high tension?', '["Vicryl", "Nylon or Prolene (Non-absorbable monofilament)", "Silk", "None"]', 1, 'Monofilaments have lower infection risk. (Schwartz''s Ch. 7)'),
    (v_topic_id, '129: "Laparoscopic" surgery involves insufflation of the abdomen with:', '["Oxygen", "Carbon Dioxide (CO2)", "Nitrogen", "None"]', 1, 'CO2 is absorbed easily and non-combustible. (de Virgilio Ch. 21)'),
    (v_topic_id, '130: A major risk of CO2 insufflation during laparoscopy is:', '["Hypocapnia", "Hypercarbia and Respiratory Acidosis", "Air embolism", "Both 2 and 3"]', 3, 'Requires adjustment of ventilation. (Mont Reid Ch. 1)'),
    (v_topic_id, '131: "Absorbable" sutures like PDS are preferred for closing the ____ in abdominal surgery.', '["Skin", "Fascia", "Subcutaneous fat", "None"]', 1, 'Maintains strength long enough for fascia to heal. (Schwartz''s Ch. 7)'),
    (v_topic_id, '132: "Vicryl" (Polyglactin 910) is a ____ suture.', '["Monofilament", "Braided", "Natural", "None"]', 1, 'Very common for deep dermal and bowel closure. (de Virgilio Ch. 7)'),
    (v_topic_id, '133: "Prolene" (Polypropylene) is a non-absorbable monofilament often used for:', '["Bowel anastomosis", "Vascular anastomosis", "Fat", "None"]', 1, 'Smooth surface prevents damage to vessels. (Mont Reid Ch. 1)'),
    (v_topic_id, '134: What is the primary purpose of a "Surgical Drain" (e.g., Jackson-Pratt)?', '["To prevent adhesions", "To eliminate dead space and evacuate fluid/blood", "To give antibiotics", "None"]', 1, 'Prevents seromas and hematomas. (Schwartz''s Ch. 7)'),
    (v_topic_id, '135: "Penrose Drains" work by ____ drainage.', '["Suction", "Gravity / Capillary action (Passive)", "Pump", "None"]', 1, 'Often used for soft tissue abscesses. (de Virgilio Ch. 6)'),
    (v_topic_id, '136: "Lidocaine" with Epinephrine is contraindicated in which areas?', '["Abdomen", "Fingers, toes, nose, penis, and ears", "Thigh", "None"]', 1, 'Risk of terminal artery vasoconstriction and necrosis. (Mont Reid Ch. 1)'),
    (v_topic_id, '137: "Bupivacaine" (Marcaine) has a ____ duration of action than Lidocaine.', '["Shorter", "Longer", "Same", "None"]', 1, 'Used for long-lasting post-op analgesia. (Schwartz''s Ch. 11)'),
    (v_topic_id, '138: "General Anesthesia" involves the triad of hypnosis, analgesia, and:', '["Fever", "Muscle relaxation (paralysis)", "Vomiting", "None"]', 1, 'Requires airway protection. (de Virgilio Ch. 1)'),
    (v_topic_id, '139: "Succinylcholine" is a depolarizing neuromuscular blocker that can cause:', '["Hypokalemia", "Hyperkalemia", "Hyponatremia", "None"]', 1, 'Dangerous in burn/crush injury patients. (Mont Reid Ch. 1)'),
    (v_topic_id, '140: What is the reversal agent for non-depolarizing blockers (e.g., Rocuronium)?', '["Naloxone", "Neostigmine + Glycopyrrolate", "Vitamin K", "None"]', 1, 'Sugammadex is also a modern specific reversal agent. (Schwartz''s Ch. 11)'),
    (v_topic_id, '141: "Ketamine" is unique among anesthetics for causing:', '["Hypotension", "Sympathetic stimulation (tachycardia/HTN)", "Respiratory depression", "None"]', 1, 'Also causes dissociative state and hallucinations. (de Virgilio Ch. 1)'),
    (v_topic_id, '142: "Propofol" is known for its rapid onset/offset and potential side effect of:', '["Liver failure", "Hypotension and respiratory depression", "Seizures", "None"]', 1, 'The "milk of amnesia." (Mont Reid Ch. 1)'),
    (v_topic_id, '143: "Spinal Anesthesia" is injected into the:', '["Epidural space", "Subarachnoid space (CSF)", "Fat", "None"]', 1, 'Typically at L3-L4 or L4-L5. (Schwartz''s Ch. 11)'),
    (v_topic_id, '144: "Epidural Anesthesia" involves placing a catheter into the space ____ to the dura.', '["Deep", "Superficial (External)", "Inside", "None"]', 1, 'Allows for continuous infusion of meds. (de Virgilio Ch. 1)'),
    (v_topic_id, '145: A common side effect of neuraxial anesthesia (spinal/epidural) is:', '["Hypertension", "Hypotension (due to sympathetic block)", "Tachycardia", "None"]', 1, 'Vasodilation causes pooling in the legs. (Mont Reid Ch. 1)'),
    (v_topic_id, '146: "Naloxone" (Narcan) is used to reverse:', '["Benzodiazepines", "Opioids", "Muscle relaxants", "None"]', 1, 'Competes at the mu receptor. (Schwartz''s Ch. 11)'),
    (v_topic_id, '147: "Flumazenil" is used to reverse:', '["Morphine", "Benzodiazepines", "Warfarin", "None"]', 1, 'Can precipitate seizures in chronic users. (de Virgilio Ch. 1)'),
    (v_topic_id, '148: What is the "standard" volume of Lactated Ringer''s used in the first hour for a trauma patient in shock?', '["500 mL", "1 Liter (Adults) or 20 mL/kg (Peds)", "5 Liters", "None"]', 1, 'Current ATLS focuses on early blood if severely shocked. (Mont Reid Ch. 3)'),
    (v_topic_id, '149: "Compartment Syndrome" is a surgical emergency characterized by pain out of proportion and:', '["Fever", "Paresthesia, Pulselessness, Pallor, Paralysis", "Hives", "None"]', 1, 'Diagnosis is clinical; treatment is fasciotomy. (Schwartz''s Ch. 7)'),
    (v_topic_id, '150: What is the "lethal triad" in trauma?', '["Acidosis, Coagulopathy, and Hypothermia", "Bleeding, Pain, and Sepsis", "Stroke, MI, and PE", "None"]', 0, 'Management focuses on "Damage Control Surgery." (de Virgilio Ch. 4)'),
    (v_topic_id, '151: "Secondary Survey" in trauma begins only AFTER:', '["Primary survey and resuscitation are complete/stable", "Patient arrives", "CT is done", "None"]', 0, 'A head-to-toe thorough evaluation. (Mont Reid Ch. 3)'),
    (v_topic_id, '152: In a "Pelvic Fracture" with hypotension, what is the first stabilization step?', '["Laparotomy", "Pelvic binder/sheet", "Angiography", "None"]', 1, 'Reduces pelvic volume to tamponade bleeding. (Schwartz''s Ch. 7)'),
    (v_topic_id, '153: A "Positive FAST" exam in an UNSTABLE patient with blunt trauma is an indication for:', '["CT scan", "Emergency Laparotomy", "Observation", "None"]', 1, 'Don''t take unstable patients to CT. (de Virgilio Ch. 4)'),
    (v_topic_id, '154: What is the most commonly injured organ in "Blunt" abdominal trauma?', '["Liver", "Spleen", "Kidney", "Stomach"]', 1, 'Followed by the liver. (Mont Reid Ch. 3)'),
    (v_topic_id, '155: What is the most commonly injured organ in "Penetrating" abdominal trauma (GSW)?', '["Liver", "Small Bowel", "Colon", "Spleen"]', 1, 'High energy causes multiple injuries. (Schwartz''s Ch. 7)'),
    (v_topic_id, '156: "Tension Pneumothorax" causes a shift of the trachea ____ the affected side.', '["Toward", "Away from", "Downward", "None"]', 1, 'Due to massive pressure buildup. (de Virgilio Ch. 4)'),
    (v_topic_id, '157: "Massive Hemothorax" is defined as > ____ mL of blood on chest tube insertion.', '["500", "1500 (or 200 mL/hr for 3 hours)", "100", "None"]', 1, 'Indication for thoracotomy. (Mont Reid Ch. 3)'),
    (v_topic_id, '158: "Cardiac Tamponade" on ultrasound shows:', '["Large heart", "Fluid in the pericardial sac and RV collapse", "Blood in lungs", "None"]', 1, 'Impaired diastolic filling. (Schwartz''s Ch. 7)'),
    (v_topic_id, '159: "Traumatic Diaphragmatic Injury" is more common on the ____ side.', '["Right", "Left", "Both equally", "None"]', 1, 'The liver protects the right side. (de Virgilio Ch. 4)'),
    (v_topic_id, '160: "Abdominal Compartment Syndrome" is defined as intra-abdominal pressure > ____ mmHg with organ dysfunction.', '["5", "10", "20", "None"]', 2, 'Treated with decompressive laparotomy. (Mont Reid Ch. 3)'),
    (v_topic_id, '161: Which burn area requires Referral to a Burn Center?', '["Small 1st degree", "Hands, feet, face, genitalia, or joints", "Minor thigh burn", "None"]', 1, 'High risk of functional or cosmetic disability. (Schwartz''s Ch. 8)'),
    (v_topic_id, '162: "Silver Sulfadiazine" (Silvadene) is a common topical burn med but can cause:', '["Liver failure", "Transient Leukopenia", "High fever", "None"]', 1, 'Also avoided in sulfa allergy. (de Virgilio Ch. 12)'),
    (v_topic_id, '163: "Mafenide Acetate" (Sulfamylon) is unique for penetrating eschar but can cause:', '["Alkalosis", "Metabolic Acidosis (Carbonic anhydrase inhibition)", "Seizures", "None"]', 1, 'Used in infected/deep ear burns. (Mont Reid Ch. 6)'),
    (v_topic_id, '164: In "Electrical Burns," the biggest threat to life is:', '["Skin burn", "Cardiac arrhythmias and Myoglobinuria (Renal failure)", "Bone pain", "None"]', 1, 'Check for high CK and tea-colored urine. (Schwartz''s Ch. 8)'),
    (v_topic_id, '165: "Circulatory Overload" in burn resuscitation leads to:', '["Dehydration", "Pulmonary edema and ACS", "Fast healing", "None"]', 1, '"Fluid creep." (de Virgilio Ch. 12)'),
    (v_topic_id, '166: "Avascular" tissue in a wound is called:', '["Slough", "Eschar", "Granulation", "Both 1 and 2"]', 3, 'Must be debrided for healing to occur. (Mont Reid Ch. 1)'),
    (v_topic_id, '167: "Granulation Tissue" is a sign of healthy healing and appears:', '["Yellow and slimy", "Beefy red and granular", "Black and hard", "None"]', 1, 'Consists of new capillaries and fibroblasts. (Schwartz''s Ch. 9)'),
    (v_topic_id, '168: "Biofilm" in chronic wounds refers to:', '["A layer of fat", "A complex community of bacteria encased in a matrix", "A type of bandage", "None"]', 1, 'Protects bacteria from antibiotics/immune system. (de Virgilio Ch. 7)'),
    (v_topic_id, '169: "Venous Stasis Ulcers" are typically located near the:', '["Pressure points (heel)", "Medial Malleolus", "Toes", "None"]', 1, 'Associated with hyperpigmentation and edema. (Mont Reid Ch. 1)'),
    (v_topic_id, '170: "Arterial Ulcers" are typically located at the ____ and are very painful.', '["Medial malleolus", "Tips of the toes or pressure points", "Calf", "None"]', 1, '"Punched out" appearance. (Schwartz''s Ch. 9)'),
    (v_topic_id, '171: "Diabetic Foot Ulcers" are primarily due to:', '["Neuropathy and Microvascular disease", "High sugar", "Poor hygiene", "None"]', 0, 'Loss of protective sensation (LOPS). (de Virgilio Ch. 7)'),
    (v_topic_id, '172: "Pressure Ulcers" (Decubitus) Stage 2 involves:', '["Redness only", "Partial thickness loss of dermis (blister/abrasion)", "Fat exposure", "Bone exposure"]', 1, 'Stage 4 involves bone/muscle. (Mont Reid Ch. 1)'),
    (v_topic_id, '173: "Negative Pressure Wound Therapy" (Wound Vac) works by:', '["Applying antibiotics", "Reducing edema and promoting granulation", "Freezing the wound", "None"]', 1, 'Increases local blood flow. (Schwartz''s Ch. 9)'),
    (v_topic_id, '174: "Skin Grafting" (Split-thickness) requires a ____ wound bed.', '["Infected", "Vascularized (Granulating)", "Bone-exposed", "None"]', 1, 'Won''t take on bare bone/tendon without periosteum/paratenon. (de Virgilio Ch. 12)'),
    (v_topic_id, '175: "Autograft" refers to tissue from:', '["A different species", "A different person", "The patient themselves", "None"]', 2, 'Allograft is from another human. (Mont Reid Ch. 6)'),
    (v_topic_id, '176: "TPN" should be initiated through a Central Line because of its high:', '["Volume", "Osmolarity (> 900 mOsm/L)", "Cost", "None"]', 1, 'Causes phlebitis in small veins. (Schwartz''s Ch. 2)'),
    (v_topic_id, '177: Which lab value is the best marker for "short-term" nutritional changes (half-life 2 days)?', '["Albumin", "Pre-albumin", "Transferrin", "Creatinine"]', 1, 'Albumin half-life is ~20 days. (de Virgilio Ch. 7)'),
    (v_topic_id, '178: "Anergy" (failure to react to skin tests like mumps/candida) is a sign of:', '["High immunity", "Severe malnutrition / Impaired cellular immunity", "Allergy", "None"]', 1, 'Correlates with high post-op risk. (Mont Reid Ch. 1)'),
    (v_topic_id, '179: A "Respiratory Quotient" (RQ) > 1.0 indicates:', '["Starvation", "Overfeeding (Lipogenesis)", "Fat metabolism", "Protein metabolism"]', 1, 'Body is converting excess glucose to fat. (Schwartz''s Ch. 2)'),
    (v_topic_id, '180: What is the primary fuel for the brain during prolonged starvation (after 3 days)?', '["Glucose", "Ketone bodies", "Fatty acids", "Amino acids"]', 1, 'Brain adapts to spare protein. (de Virgilio Ch. 7)'),
    (v_topic_id, '181: "Respiratory Quotient" (RQ) of 0.7 indicates:', '["Pure carbohydrate use", "Pure fat use", "Mixed diet", "None"]', 1, 'Carbohydrate RQ is 1.0. (Mont Reid Ch. 1)'),
    (v_topic_id, '182: "Indirect Calorimetry" measures energy expenditure via:', '["Weight", "Oxygen consumption and CO2 production", "Blood tests", "None"]', 1, 'Gold standard for calculating kcal needs. (Schwartz''s Ch. 2)'),
    (v_topic_id, '183: "Sarcopenia" refers to the loss of:', '["Fat", "Skeletal muscle mass and strength", "Bone", "None"]', 1, 'Common in elderly surgical patients. (de Virgilio Ch. 7)'),
    (v_topic_id, '184: "Basal Metabolic Rate" (BMR) is often estimated using the:', '["GCS Scale", "Harris-Benedict Equation", "Parkland Formula", "None"]', 1, 'Adjusted for stress/activity level. (Mont Reid Ch. 1)'),
    (v_topic_id, '185: "Laparoscopic" surgery generally results in ____ systemic inflammatory response compared to open.', '["Greater", "Lesser", "Identical", "None"]', 1, 'One of the many benefits of MIS. (Schwartz''s Ch. 21)'),
    (v_topic_id, '186: "Trocar" injury during laparoscopy most commonly involves:', '["Bowel or major vessels (Aorta/Iliacs)", "Skin only", "Lungs", "None"]', 0, 'Veress needle entry is also high risk. (de Virgilio Ch. 21)'),
    (v_topic_id, '187: "Pneumoperitoneum" decreases ____ and increases ____.', '["Heart rate; BP", "Venous return; Systemic Vascular Resistance", "Urine; Appetite", "None"]', 1, 'Due to increased intra-abdominal pressure. (Mont Reid Ch. 1)'),
    (v_topic_id, '188: "Electrocautery" (Monopolar) requires a:', '["Water bath", "Grounding pad on the patient", "Laser", "None"]', 1, 'Current flows from the tip through the patient to the pad. (Schwartz''s Ch. 11)'),
    (v_topic_id, '189: "Bipolar" cautery is safer for patients with:', '["Pacemakers", "Anemia", "Fever", "None"]', 0, 'Current only flows between the two tips of the instrument. (de Virgilio Ch. 21)'),
    (v_topic_id, '190: "Surgical Smoke" from cautery contains:', '["Vitamins", "Biohazardous chemicals and potentially viral particles", "Only steam", "None"]', 1, 'Smoke evacuation is recommended. (Mont Reid Ch. 1)'),
    (v_topic_id, '191: "ERAS" (Enhanced Recovery After Surgery) protocols focus on:', '["Long NPO times", "Early mobilization, nutrition, and non-opioid analgesia", "Bed rest", "None"]', 1, 'Reduces hospital stay and complications. (Schwartz''s Ch. 11)'),
    (v_topic_id, '192: "Post-op Nausea and Vomiting" (PONV) risk is highest in:', '["Older men", "Young non-smoking women", "Children", "None"]', 1, 'Also history of motion sickness. (de Virgilio Ch. 1)'),
    (v_topic_id, '193: "Scopolamine" patches for PONV are applied:', '["On the wound", "Behind the ear (preoperatively)", "On the foot", "None"]', 1, 'Anticholinergic medication. (Mont Reid Ch. 1)'),
    (v_topic_id, '194: "Ondansetron" (Zofran) is a ____ antagonist.', '["Dopamine", "5-HT3 (Serotonin)", "Histamine", "None"]', 1, 'Very effective for post-op nausea. (Schwartz''s Ch. 11)'),
    (v_topic_id, '195: A patient with "Sudden Desaturation" in the recovery room should first have their:', '["Blood pressure checked", "Airway assessed and given Oxygen", "Incision checked", "None"]', 1, 'ABC priority. (de Virgilio Ch. 1)'),
    (v_topic_id, '196: "Intra-op Hypotension" after anesthesia induction is usually due to:', '["Bleeding", "Vasodilation from meds and relative hypovolemia", "Sepsis", "None"]', 1, 'Treated with fluids/pressors. (Mont Reid Ch. 1)'),
    (v_topic_id, '197: "Surgical Timeout" must be done ____.', '["After the case", "Before the first incision", "In the office", "None"]', 1, 'Confirms patient, site, and procedure. (Schwartz''s Ch. 11)'),
    (v_topic_id, '198: "Wound Classification" should be determined ____.', '["At the end of the procedure", "At the start", "Next day", "None"]', 0, 'Based on the findings during surgery. (de Virgilio Ch. 6)'),
    (v_topic_id, '199: "Laparotomy" refers to a ____ incision into the abdomen.', '["Small", "Large surgical", "Invisible", "None"]', 1, 'Usually midline. (Mont Reid Ch. 1)'),
    (v_topic_id, '200: What is the most common "preventable" cause of death in surgical patients?', '["Infection", "Venous Thromboembolism (PE)", "Heart attack", "Stroke"]', 1, 'Highlighting the importance of VTE prophylaxis. (Schwartz''s Ch. 11)');
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '201: "Hypocalcemia" after thyroid/parathyroid surgery is due to injury to the:', '["Recurrent laryngeal nerve", "Parathyroid glands", "Trachea", "None"]', 1, 'Monitor for Chvostek''s and Trousseau''s signs. (Schwartz''s Ch. 38)'),
    (v_topic_id, '202: "Chvostek''s Sign" is elicited by:', '["Inflating a BP cuff", "Tapping on the facial nerve", "Flexing the hip", "None"]', 1, 'Causes facial twitching in hypocalcemia. (de Virgilio Ch. 2)'),
    (v_topic_id, '203: "Trousseau''s Sign" is elicited by:', '["Tapping the face", "Inflating a BP cuff above systolic for 3 min", "Rubbing the chest", "None"]', 1, 'Causes carpal spasm in hypocalcemia. (Mont Reid Ch. 2)'),
    (v_topic_id, '204: "Hypoparathyroidism" causes ____ Calcium and ____ Phosphate.', '["High; Low", "Low; High", "Low; Low", "None"]', 1, 'PTH normally raises Ca and lowers PO4. (Schwartz''s Ch. 3)'),
    (v_topic_id, '205: "Pseudohypoparathyroidism" is characterized by:', '["Low PTH", "End-organ resistance to PTH", "High Vitamin D", "None"]', 1, 'Albright hereditary osteodystrophy. (de Virgilio Ch. 2)'),
    (v_topic_id, '206: "Hypercalcemia" in a surgical patient is most commonly due to:', '["Renal failure", "Primary Hyperparathyroidism or Malignancy", "Too much milk", "None"]', 1, '"Stones, bones, groans, and psychic overtones." (Mont Reid Ch. 2)'),
    (v_topic_id, '207: "Hungry Bone Syndrome" follows parathyroidectomy and leads to:', '["Hypercalcemia", "Severe Hypocalcemia", "Fever", "None"]', 1, 'Bone rapidly absorbs Ca after PTH removal. (Schwartz''s Ch. 3)'),
    (v_topic_id, '208: What is the first-line treatment for "Severe Hypercalcemia"?', '["Furosemide", "Aggressive IV Saline and Bisphosphonates", "Dialysis", "None"]', 1, 'Saline promotes renal Ca excretion. (de Virgilio Ch. 2)'),
    (v_topic_id, '209: "Hyperphosphatemia" is almost always due to:', '["Diet", "Renal failure", "Thyroid surgery", "None"]', 1, 'Inability to excrete phosphorus. (Mont Reid Ch. 2)'),
    (v_topic_id, '210: "Central Diabetes Insipidus" presents with polyuria and:', '["Hyponatremia", "Hypernatremia", "Hypoglycemia", "None"]', 1, 'Inability to secrete ADH. (Schwartz''s Ch. 3)'),
    (v_topic_id, '211: "Desmopressin" is used to treat which form of DI?', '["Nephrogenic", "Central", "Both", "None"]', 1, 'Acts as an ADH replacement. (de Virgilio Ch. 2)'),
    (v_topic_id, '212: "SIADH" (excess ADH) leads to:', '["Hypernatremic dehydration", "Dilutional hyponatremia", "High sugar", "None"]', 1, 'Urine is inappropriately concentrated. (Mont Reid Ch. 2)'),
    (v_topic_id, '213: A "pauci-immune" state in surgery leads to:', '["Faster healing", "Increased risk of opportunistic infections", "High energy", "None"]', 1, 'Often seen in severe trauma/sepsis. (Schwartz''s Ch. 5)'),
    (v_topic_id, '214: "Dextran" and "Hetastarch" are synthetic colloids that can cause:', '["Better healing", "Coagulopathy and Renal failure", "Weight loss", "None"]', 1, 'Interfere with platelet function. (de Virgilio Ch. 2)'),
    (v_topic_id, '215: "Citrate toxicity" in massive transfusion is treated with:', '["Magnesium", "Calcium Gluconate", "Insulin", "None"]', 1, 'Citrate chelates calcium. (Mont Reid Ch. 4)'),
    (v_topic_id, '216: "Platelets" for transfusion should be stored at:', '["Freezer", "Room temperature (with agitation)", "Refrigerator", "None"]', 1, 'High risk of bacterial contamination. (Schwartz''s Ch. 4)'),
    (v_topic_id, '217: "Cross-matching" for blood transfusion involves mixing:', '["Recipient serum and Donor red cells", "Donor serum and Recipient cells", "Water and blood", "None"]', 0, 'Final check for compatibility. (de Virgilio Ch. 3)'),
    (v_topic_id, '218: "Emergency Release" blood is:', '["Type O negative (universal)", "Type AB positive", "Any blood available", "None"]', 0, 'Used when life-threatening bleeding occurs before cross-match. (Mont Reid Ch. 4)'),
    (v_topic_id, '219: "Factor V Leiden" is the most common cause of:', '["Bleeding", "Inherited Hypercoagulability", "Fever", "None"]', 1, 'Resistance to Activated Protein C. (Schwartz''s Ch. 4)'),
    (v_topic_id, '220: "Antithrombin III" deficiency can make a patient resistant to:', '["Warfarin", "Heparin", "Aspirin", "None"]', 1, 'Heparin requires ATIII to work. (de Virgilio Ch. 3)'),
    (v_topic_id, '221: "HIT" (Heparin-Induced Thrombocytopenia) Type II is caused by antibodies to:', '["Factor X", "Platelet Factor 4 (PF4)-Heparin complex", "Factor VIII", "None"]', 1, 'Paradoxically causes clotting (thrombosis). (Mont Reid Ch. 4)'),
    (v_topic_id, '222: If a patient develops "HIT," what is the next step?', '["Increase Heparin", "Stop all Heparin and start a Direct Thrombin Inhibitor (e.g., Argatroban)", "Give Platelets", "None"]', 1, 'Platelet transfusion is generally avoided. (Schwartz''s Ch. 4)'),
    (v_topic_id, '223: "Protein C and S" are natural:', '["Clotting factors", "Anticoagulants", "Vitamins", "None"]', 1, 'Inhibit Factors Va and VIIIa. (de Virgilio Ch. 3)'),
    (v_topic_id, '224: "Warfarin-Induced Skin Necrosis" occurs in patients with:', '["Vitamin C deficiency", "Protein C or S deficiency", "Diabetes", "None"]', 1, 'Protein C (short half-life) drops first, creating a pro-thrombotic state. (Mont Reid Ch. 4)'),
    (v_topic_id, '225: "Tranexamic Acid" (TXA) works by:', '["Inhibiting thrombin", "Inhibiting fibrinolysis (plasminogen activation)", "Activating platelets", "None"]', 1, 'Used in trauma and postpartum hemorrhage. (Schwartz''s Ch. 4)'),
    (v_topic_id, '226: "SIRS" (Systemic Inflammatory Response Syndrome) requires 2 or more of: Temp > 38, HR > 90, RR > 20, and:', '["BP < 90", "WBC > 12,000 or < 4,000", "Lactate > 4", "None"]', 1, 'Now superseded by SOFA for sepsis, but still tested. (de Virgilio Ch. 5)'),
    (v_topic_id, '227: "SOFA" score stands for:', '["Simple Organ Failure Assessment", "Sequential Organ Failure Assessment", "Surgical Outcome", "None"]', 1, 'Includes PaO2, Platelets, Bilirubin, BP, GCS, and Creatinine. (Mont Reid Ch. 3)'),
    (v_topic_id, '228: "qSOFA" bedside tool includes RR >= 22, Altered Mental Status, and:', '["Fever", "Systolic BP <= 100", "Heart rate > 100", "None"]', 1, 'Quick screen for sepsis mortality risk. (Schwartz''s Ch. 5)'),
    (v_topic_id, '229: What is the most common "nosocomial" (hospital-acquired) infection?', '["Pneumonia", "UTI (Catheter-associated)", "SSI", "C. diff"]', 1, 'Usually E. coli. (de Virgilio Ch. 6)'),
    (v_topic_id, '230: "Early" Surgical Debridement for Necrotizing Fasciitis is defined as within:', '["24 hours", "6 hours", "1 week", "None"]', 1, 'Every hour delay increases mortality. (Mont Reid Ch. 5)'),
    (v_topic_id, '231: "Group A Strep" (S. pyogenes) and "S. aureus" are the most common causes of:', '["Abscess", "Cellulitis", "Meningitis", "None"]', 1, 'Non-purulent vs. purulent cellulitis. (Schwartz''s Ch. 6)'),
    (v_topic_id, '232: "Fournier''s Gangrene" is necrotizing fasciitis of the:', '["Leg", "Perineum and scrotum", "Arm", "None"]', 1, 'Often in diabetic males. (de Virgilio Ch. 6)'),
    (v_topic_id, '233: "Gas in the portal vein" on CT is an ominous sign of:', '["Constipation", "Bowel infarction / Ischemia", "Gallstones", "None"]', 1, 'Requires emergent exploration. (Mont Reid Ch. 5)'),
    (v_topic_id, '234: "Pneumoperitoneum" on upright CXR indicates:', '["Pneumonia", "Hollow viscus perforation (e.g., Peptic ulcer)", "Heart failure", "None"]', 1, 'Surgical emergency. (Schwartz''s Ch. 26)'),
    (v_topic_id, '235: "Primary Survey" is intended to identify:', '["All fractures", "Immediate life-threatening injuries", "The patient''s family", "None"]', 1, 'ABCDE approach. (de Virgilio Ch. 4)'),
    (v_topic_id, '236: "GCS" (Glasgow Coma Scale) of 8 or less requires:', '["Oxygen mask", "Endotracheal Intubation", "Wait and see", "None"]', 1, 'Inability to protect airway. (Mont Reid Ch. 3)'),
    (v_topic_id, '237: A "Seatbelt Sign" on the abdomen should raise suspicion for:', '["Lungs", "Small bowel or Lumbar spine (Chance) fracture", "Heart", "None"]', 1, 'Compression against the spine. (Schwartz''s Ch. 7)'),
    (v_topic_id, '238: "Retroperitoneal" organs (SAD PUCKER) include the Duodenum (2nd/3rd), Pancreas, and:', '["Spleen", "Kidneys", "Stomach", "None"]', 1, 'Fluid/blood here may not be seen on FAST. (de Virgilio Ch. 4)'),
    (v_topic_id, '239: "Diagnostic Peritoneal Aspirate" (DPA) is the fast version of:', '["CT", "DPL (Lavage)", "MRI", "None"]', 1, 'Positive if > 10 mL of frank blood is aspirated. (Mont Reid Ch. 3)'),
    (v_topic_id, '240: "Urethral injury" in a male should be suspected if there is "blood at the meatus" or "high-riding prostate." What is the next test?', '["Catheterization", "Retrograde Urethrogram (RUG)", "Cystoscopy", "None"]', 1, 'Do not insert a Foley if urethral injury is suspected. (Schwartz''s Ch. 7)'),
    (v_topic_id, '241: "Flail Chest" is primarily treated with:', '["Rib plates", "Adequate pain control and pulmonary toilet", "Sandbags", "None"]', 1, 'Intubation only if respiratory failure occurs. (de Virgilio Ch. 4)'),
    (v_topic_id, '242: "Pulmonary Contusion" on CXR often takes ____ to appear.', '["1 minute", "24-48 hours", "1 week", "None"]', 1, '"White out" of the lung field after trauma. (Mont Reid Ch. 3)'),
    (v_topic_id, '243: "Aortic Rupture" in trauma classically occurs at the:', '["Aortic arch", "Aortic isthmus (just distal to L subclavian)", "Abdominal aorta", "None"]', 1, 'Point of ligamentum arteriosum attachment. (Schwartz''s Ch. 7)'),
    (v_topic_id, '244: "Blunt Cardiac Injury" (BCI) is most commonly diagnosed by:', '["MRI", "ECG and Troponins", "CT", "None"]', 1, 'Monitor for arrhythmias. (de Virgilio Ch. 4)'),
    (v_topic_id, '245: "Splenic Injury" Grade IV or V usually requires:', '["Observation", "Splenectomy or Angio-embolization", "Aspirin", "None"]', 1, 'Depending on hemodynamic stability. (Mont Reid Ch. 3)'),
    (v_topic_id, '246: Patients after "Splenectomy" require vaccines against encapsulated organisms (Strep pneu, H. flu, and ____).', '["E. coli", "Neisseria meningitidis", "Listeria", "None"]', 1, 'To prevent OPSI (Overwhelming Post-Splenectomy Infection). (Schwartz''s Ch. 34)'),
    (v_topic_id, '247: "Damage Control Laparotomy" focus is on:', '["Definitive repair of all injuries", "Control of hemorrhage and contamination (fast)", "Cosmetic closure", "None"]', 1, 'Pack the patient and go to ICU for resuscitation. (de Virgilio Ch. 4)'),
    (v_topic_id, '248: "Kehr''s Sign" is referred pain to the ____ shoulder due to splenic rupture.', '["Right", "Left", "Both", "None"]', 1, 'Due to diaphragmatic irritation. (Mont Reid Ch. 3)'),
    (v_topic_id, '249: "Seatbelt Syndrome" consists of abdominal wall bruising, bowel injury, and ____.', '["Limb fracture", "Chance fracture (Lumbar spine)", "Skull fracture", "None"]', 1, 'Horizontal distraction fracture. (Schwartz''s Ch. 7)'),
    (v_topic_id, '250: What is the most common cause of death in people under 45?', '["Cancer", "Trauma", "Heart disease", "Infection"]', 1, 'Trauma remains a major public health issue. (de Virgilio Ch. 4)'),
    (v_topic_id, '251: In the Parkland formula, half of the fluid is given in the first 8 hours ____.', '["From arrival", "From the time of injury", "From the time of consult", "None"]', 1, 'Clock starts at the time of the burn. (Mont Reid Ch. 6)'),
    (v_topic_id, '252: "Inhalation Injury" requires a high index of suspicion with facial burns and ____.', '["Hoarseness / Singed nasal hairs", "Leg pain", "Fast heart rate", "None"]', 0, 'Early intubation may be necessary before airway swells. (Schwartz''s Ch. 8)'),
    (v_topic_id, '253: "Carbon Monoxide" has a ____-fold higher affinity for hemoglobin than oxygen.', '["2", "10", "200", "None"]', 2, 'Causes a left shift in the dissociation curve. (de Virgilio Ch. 12)'),
    (v_topic_id, '254: "Cyanide Toxicity" in fire victims presents with unexplained:', '["Alkalosis", "Severe Lactic Acidosis", "Fever", "None"]', 1, 'Treated with Hydroxocobalamin. (Mont Reid Ch. 6)'),
    (v_topic_id, '255: "Chemical Burns" with powders should be:', '["Washed with water immediately", "Brushed off before irrigation", "Left alone", "None"]', 1, 'Water may activate some chemicals (e.g., lime). (Schwartz''s Ch. 8)'),
    (v_topic_id, '256: "Hydrofluoric Acid" burns are treated with topical ____.', '["Water only", "Calcium gluconate gel", "Vinegar", "None"]', 1, 'Fluoride binds calcium, causing pain and arrhythmias. (de Virgilio Ch. 12)'),
    (v_topic_id, '257: "Burn Shock" is primarily:', '["Cardiogenic", "Hypovolemic and Distributive", "Septic", "None"]', 1, 'Due to massive fluid shift and capillary leak. (Mont Reid Ch. 6)'),
    (v_topic_id, '258: "Early Excision and Grafting" of burns (within 72 hrs) is shown to:', '["Increase mortality", "Reduce sepsis and hospital stay", "No effect", "None"]', 1, 'Removing necrotic tissue is fundamental. (Schwartz''s Ch. 8)'),
    (v_topic_id, '259: "Amniotic Membrane" is a type of ____ used in burn care.', '["Autograft", "Biological dressing (Allograft)", "Synthetic", "None"]', 1, 'Temporary coverage. (de Virgilio Ch. 12)'),
    (v_topic_id, '260: "Full-thickness" grafts (FTSG) include the entire:', '["Epidermis", "Dermis", "Muscle", "None"]', 1, 'Less contraction but poorer "take" than STSG. (Mont Reid Ch. 6)'),
    (v_topic_id, '261: "Vitamin A" can help reverse the wound-healing inhibition caused by:', '["Antibiotics", "Steroids", "NSAIDs", "None"]', 1, 'Restores inflammatory response. (Schwartz''s Ch. 9)'),
    (v_topic_id, '262: "Zinc" deficiency classically presents with a perioral/acral rash known as:', '["Hives", "Acrodermatitis enteropathica", "Psoriasis", "None"]', 1, 'Also causes delayed wound healing. (de Virgilio Ch. 7)'),
    (v_topic_id, '263: "Chronic wounds" are those that fail to progress through healing in ____ weeks.', '["1", "4-12", "52", "None"]', 1, 'Often stuck in the inflammatory phase. (Mont Reid Ch. 1)'),
    (v_topic_id, '264: "Marjolin''s Ulcer" is a ____ developing in a chronic scar or burn.', '["Infection", "Squamous Cell Carcinoma", "Abscess", "None"]', 1, 'Highly aggressive cancer. (Schwartz''s Ch. 14)'),
    (v_topic_id, '265: "Wound Contraction" is mediated by:', '["Neutrophils", "Myofibroblasts", "Fat cells", "None"]', 1, 'Specialized fibroblasts with contractile properties. (de Virgilio Ch. 7)'),
    (v_topic_id, '266: "Seroma" is a collection of ____ in a surgical wound.', '["Pus", "Serous fluid (clear/yellow)", "Blood", "None"]', 1, 'Treated with aspiration or drainage. (Mont Reid Ch. 1)'),
    (v_topic_id, '267: "Hematoma" in the neck after thyroid surgery is a life-threatening emergency because of:', '["Anemia", "Airway compression", "Infection", "None"]', 1, 'Requires immediate bedside opening of the wound. (Schwartz''s Ch. 38)'),
    (v_topic_id, '268: "Pyoderma Gangrenosum" is an inflammatory ulcer associated with:', '["Diabetes", "IBD (Crohn''s/UC)", "Cancer", "None"]', 1, 'Shows "Pathergy" (worsens with surgery/debridement). (de Virgilio Ch. 7)'),
    (v_topic_id, '269: "Calciphylaxis" is a painful necrotic skin lesion seen in patients with:', '["Asthma", "End-stage renal disease (ESRD)", "Liver failure", "None"]', 1, 'Due to calcium deposition in small vessels. (Mont Reid Ch. 2)'),
    (v_topic_id, '270: "Clean" wounds have a < 2% infection rate. What is the rate for "Dirty" wounds (existing infection)?', '["5%", "15%", "Up to 40%", "None"]', 2, 'Requires therapeutic antibiotics, not just prophylaxis. (Schwartz''s Ch. 6)'),
    (v_topic_id, '271: "Dehiscence" of a bowel anastomosis typically occurs between POD:', '["1-2", "5-7", "30", "None"]', 1, 'Check for new fever, pain, or leukocytosis. (de Virgilio Ch. 1)'),
    (v_topic_id, '272: "Gastrointestinal Fistula" management follows the "FRIEND" mnemonic. "F" stands for:', '["Food", "Foreign body (prevents closure)", "Fast", "None"]', 1, 'Reasons why fistulas don''t close spontaneously. (Mont Reid Ch. 1)'),
    (v_topic_id, '273: "Radiation" inhibits wound healing by causing:', '["Fever", "Obliterative endarteritis (reduced blood supply)", "High sugar", "None"]', 1, 'Permanent damage to small vessels. (Schwartz''s Ch. 9)'),
    (v_topic_id, '274: "Silver" is used in dressings because it is:', '["Pretty", "Antimicrobial (kills bacteria)", "Cheap", "None"]', 1, 'Commonly used for burns and chronic wounds. (de Virgilio Ch. 12)'),
    (v_topic_id, '275: "Alginate" dressings (from seaweed) are best for:', '["Dry wounds", "Highly exudative (wet) wounds", "Bone", "None"]', 1, 'Can absorb many times their weight in fluid. (Mont Reid Ch. 1)'),
    (v_topic_id, '276: "Hydrocolloids" are best for ____ wounds.', '["Heavily infected", "Low-exudate or superficial wounds", "None", "None"]', 1, 'Promotes autolytic debridement. (Schwartz''s Ch. 9)'),
    (v_topic_id, '277: "Hyperbaric Oxygen" (HBO) is most useful for which wound type?', '["Sunburn", "Diabetic foot ulcers with ischemia / Osteomyelitis", "Hives", "None"]', 1, 'Increases oxygen delivery to hypoxic tissues. (de Virgilio Ch. 7)'),
    (v_topic_id, '278: "Paralytic Ileus" affects the whole bowel. "Pseudo-obstruction" (Ogilvie) affects primarily the:', '["Stomach", "Colon", "Small bowel", "None"]', 1, 'Massive dilation without mechanical blockage. (Mont Reid Ch. 2)'),
    (v_topic_id, '279: "Neostigmine" is a pharmacologic treatment for refractory:', '["Pain", "Ogilvie Syndrome", "Fever", "None"]', 1, 'Promotes colonic motility; requires cardiac monitoring for bradycardia. (Schwartz''s Ch. 29)'),
    (v_topic_id, '280: "Post-op Delirium" in the elderly is most commonly triggered by:', '["Medications (Benardryl/Benzos), pain, or infection", "Watching TV", "Good sleep", "None"]', 0, 'Prevention is key (avoid anticholinergics). (de Virgilio Ch. 1)'),
    (v_topic_id, '281: "Aspiration Pneumonia" post-op is most common in the ____ lung.', '["Left", "Right (Right lower lobe)", "Both equally", "None"]', 1, 'Right mainstem bronchus is more vertical. (Mont Reid Ch. 1)'),
    (v_topic_id, '282: "Fat Embolism Syndrome" occurs 24-72 hrs after long bone fractures. Triad: Dyspnea, Confusion, and:', '["Fever", "Petechial rash (chest/axilla)", "Diarrhea", "None"]', 1, 'High-yield orthopedic-surgery association. (Schwartz''s Ch. 7)'),
    (v_topic_id, '283: "Air Embolism" during central line insertion is managed by placing the patient in:', '["Trendelenburg and Left Lateral Decubitus (Durant''s maneuver)", "Reverse Trendelenburg", "Sitting up", "None"]', 0, 'Traps air in the right ventricle apex away from the outflow tract. (de Virgilio Ch. 1)'),
    (v_topic_id, '284: "Malignant Hyperthermia" is due to a mutation in the ____ receptor.', '["ACh", "Ryanodine (RYR1)", "Dopamine", "None"]', 1, 'Causes uncontrolled calcium release from sarcoplasmic reticulum. (Mont Reid Ch. 1)'),
    (v_topic_id, '285: "Dantrolene" works by:', '["Blocking ACh", "Inhibiting calcium release from the sarcoplasmic reticulum", "Lowering BP", "None"]', 1, 'Specific antidote for MH. (Schwartz''s Ch. 11)'),
    (v_topic_id, '286: "Lidocaine" toxicity causes perioral numbness, metallic taste, and:', '["Fever", "Seizures and Cardiovascular collapse", "Hives", "None"]', 1, 'Maximum dose ~4-5 mg/kg (7 mg/kg with Epi). (de Virgilio Ch. 1)'),
    (v_topic_id, '287: "Post-dural Puncture Headache" (PDPH) is treated with:', '["Aspirin", "Caffeine or Epidural Blood Patch", "Exercise", "None"]', 1, 'Due to CSF leak from dural hole. (Mont Reid Ch. 1)'),
    (v_topic_id, '288: "Surgical Knot" security depends on the material. Which requires MORE throws?', '["Silk", "Monofilament (Nylon/Prolene)", "Vicryl", "None"]', 1, 'Monofilaments are "slicker" and require 5-6 throws. (Schwartz''s Ch. 7)'),
    (v_topic_id, '289: "Subtotal" gastrectomy means:', '["Part of the stomach removed", "Entire stomach removed", "Opening only", "None"]', 0, 'Total gastrectomy = entire stomach. (de Virgilio Ch. 26)'),
    (v_topic_id, '290: "Anastomosis" refers to:', '["Removing an organ", "Surgical connection between two structures", "A type of suture", "None"]', 1, 'e.g., Bowel-to-bowel. (Mont Reid Ch. 1)'),
    (v_topic_id, '291: "Stoma" refers to a piece of bowel brought to the skin. "Ileostomy" is from the:', '["Colon", "Small bowel (Ileum)", "Stomach", "None"]', 1, 'Colostomy is from the colon. (Schwartz''s Ch. 28)'),
    (v_topic_id, '292: "End" Stoma vs "Loop" Stoma: Which is usually temporary and used for diversion?', '["End", "Loop", "Both", "None"]', 1, 'Loop stomas are easier to reverse. (de Virgilio Ch. 32)'),
    (v_topic_id, '293: "Laparoscopy" is generally contraindicated in which patient?', '["Obese", "Hemodynamically unstable / Traumatic shock", "Elderly", "None"]', 1, 'Pneumoperitoneum further compromises BP. (Mont Reid Ch. 1)'),
    (v_topic_id, '294: "Hasson Technique" for laparoscopy involves:', '["Blind entry with Veress needle", "Open entry under direct visualization", "A laser", "None"]', 1, 'Safer for patients with prior abdominal surgery. (Schwartz''s Ch. 21)'),
    (v_topic_id, '295: "Veress Needle" entry is:', '["Open", "Blind", "Robotic", "None"]', 1, 'Surgeon feels for "clicks" as it passes layers. (de Virgilio Ch. 21)'),
    (v_topic_id, '296: "Robotic Surgery" (e.g., Da Vinci) provides:', '["3D vision and wristed instruments", "Faster speed", "Lower cost", "None"]', 0, 'Enhanced ergonomics and precision. (Mont Reid Ch. 1)'),
    (v_topic_id, '297: "Surgical Ergonomics" is intended to:', '["Make the patient comfortable", "Reduce physical strain on the surgeon", "Clean the OR", "None"]', 1, 'Important for long-term career health. (Schwartz''s Ch. 1)'),
    (v_topic_id, '298: "Informed Consent" is valid only if the patient has ____.', '["A lawyer", "Capacity (understanding)", "Money", "None"]', 1, 'Minors or impaired adults require a surrogate. (de Virgilio Ch. 1)'),
    (v_topic_id, '299: "Living Will" and "Power of Attorney" are forms of:', '["Insurance", "Advance Directives", "Taxes", "None"]', 1, 'Crucial for end-of-life surgical decisions. (Mont Reid Ch. 1)'),
    (v_topic_id, '300: "Beneficence" in medical ethics means:', '["Do no harm", "Acting in the patient''s best interest", "Patient autonomy", "None"]', 1, 'Non-maleficence is "Do no harm." (Schwartz''s Ch. 1)'),
    (v_topic_id, '301: "Surgical Checklist" (WHO) has been shown to:', '["Increase paperwork only", "Significantly reduce morbidity and mortality", "Increase infection", "None"]', 1, 'Safety standard globally. (de Virgilio Ch. 1)'),
    (v_topic_id, '302: "Sharp injuries" in the OR carry a risk of transmitting:', '["HBV, HCV, and HIV", "Cancer", "Stroke", "None"]', 0, 'HBV has the highest transmission risk per needle stick. (Mont Reid Ch. 1)'),
    (v_topic_id, '303: "Post-exposure prophylaxis" (PEP) for HIV should be started within:', '["1 hour", "72 hours", "1 week", "None"]', 1, 'Ideally within hours. (Schwartz''s Ch. 6)'),
    (v_topic_id, '304: "Double Gloving" is shown to:', '["Reduce the risk of inner glove perforation and needle stick exposure", "Be uncomfortable only", "Increase infection", "None"]', 0, 'Standard practice for major cases. (de Virgilio Ch. 6)'),
    (v_topic_id, '305: "Fire Triad" in the OR: Fuel, Heat, and ____.', '["Water", "Oxidizer (Oxygen/N2O)", "Wind", "None"]', 1, 'Especially a risk in head/neck surgery with open oxygen. (Mont Reid Ch. 1)'),
    (v_topic_id, '306: "Alcohol-based" skin preps (e.g., ChloraPrep) must ____ before draping.', '["Be wiped off", "Dry completely", "Be kept wet", "None"]', 1, 'Prevents surgical fires. (Schwartz''s Ch. 11)'),
    (v_topic_id, '307: "Chlorhexidine" is generally superior to Povidone-Iodine because it has:', '["Better smell", "Persistent (residual) antimicrobial activity", "Lower cost", "None"]', 1, 'Standard for most skin prep. (de Virgilio Ch. 6)'),
    (v_topic_id, '308: "Surgical Scrub" should last at least:', '["10 seconds", "2-5 minutes", "20 minutes", "None"]', 1, 'Reduces transient and resident flora. (Mont Reid Ch. 1)'),
    (v_topic_id, '309: "Gowning and Gloving" is done from a ____ surface.', '["Dirty", "Sterile", "Floor", "None"]', 1, 'Maintaining the sterile field. (Schwartz''s Ch. 11)'),
    (v_topic_id, '310: "Back of the gown" is considered ____.', '["Sterile", "Non-sterile", "Half-sterile", "None"]', 1, 'Surgeons should not turn their backs to the sterile field. (de Virgilio Ch. 6)'),
    (v_topic_id, '311: "Wound Bed Preparation" mnemonic: DIME. "D" stands for:', '["Dressing", "Debridement", "Drainage", "None"]', 1, 'Removing necrotic tissue is step one. (Mont Reid Ch. 1)'),
    (v_topic_id, '312: "I" in DIME stands for:', '["Incision", "Infection or Inflammation control", "Inpatient", "None"]', 1, 'Managing the bioburden. (Schwartz''s Ch. 9)'),
    (v_topic_id, '313: "M" in DIME stands for:', '["Maturation", "Moisture balance", "Muscle", "None"]', 1, 'Wounds heal best in a moist (not wet) environment. (de Virgilio Ch. 7)'),
    (v_topic_id, '314: "E" in DIME stands for:', '["End", "Edge of the wound (Epibole)", "Exercise", "None"]', 1, 'Ensuring the wound edges are migrating. (Mont Reid Ch. 1)'),
    (v_topic_id, '315: "Hypertrophic Scar" differs from Keloid because it:', '["Grows beyond borders", "Stays within the original wound borders", "Is malignant", "None"]', 1, 'Often improves over time/with pressure. (Schwartz''s Ch. 9)'),
    (v_topic_id, '316: "Delayed Primary Closure" is also called:', '["Primary intention", "Secondary intention", "Tertiary intention", "None"]', 2, 'Wound is left open for 3-5 days then closed. (de Virgilio Ch. 7)'),
    (v_topic_id, '317: "Tensile Strength" of a wound at 3 weeks is approximately ____%.', '["5%", "20%", "50%", "100%"]', 1, 'Strength continues to increase during the maturation phase. (Mont Reid Ch. 1)'),
    (v_topic_id, '318: "Serosanguinous" drainage refers to:', '["Pure blood", "Thin, watery, pink fluid", "Yellow pus", "None"]', 1, 'Normal in early wound healing. (Schwartz''s Ch. 9)'),
    (v_topic_id, '319: "Purulent" drainage is a sign of:', '["Health", "Infection", "Healing", "None"]', 1, 'Contains WBCs, dead tissue, and bacteria. (de Virgilio Ch. 6)'),
    (v_topic_id, '320: Final Surgical Principle: "A chance to cut is a chance to ____" (Old surgical adage).', '["Cure", "Heal", "Bleed", "None"]', 0, 'Surgery is the definitive treatment for many diseases. (Schwartz''s Ch. 1)');
