-- Migration: Year 3 - Surgical Principles MCQ Bank (COMPLETE: 1-320)
-- Based on Schwartz's 11th Ed, de Virgilio 2nd Ed, and Mont Reid 6th Ed.
-- This file is IDEMPOTENT: It deletes existing records before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'surgical-principles' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Preoperative Evaluation and Risk Assessment

    -- SECTION 2: Fluids, Electrolytes, and Acid-Base
    (v_topic_id, '16: What is the estimated total body water (TBW) percentage in an average 70 kg man?', '["40%", "50%", "60%", "80%"]', 2, '60% in men, 50% in women. (Schwartz''s Ch. 3)'),
    (v_topic_id, '17: Which fluid compartment holds the largest percentage of total body water?', '["Extracellular (ECF)", "Intracellular (ICF)", "Plasma", "Interstitial"]', 1, 'ICF holds about 2/3 of TBW. (de Virgilio Ch. 2)'),
    (v_topic_id, '18: What is the most common cause of "postoperative hyponatremia"?', '["Salt wasting", "Excessive IV free water (D5W) and ADH secretion", "Diuretics", "None"]', 1, 'SIADH-like state following surgical stress. (Mont Reid Ch. 2)'),
    (v_topic_id, '19: "Hyperkalemia" (K > 5.5) on ECG is first manifested by:', '["U waves", "Peaked T waves", "ST depression", "Flattened P waves"]', 1, 'Followed by PR prolongation and widened QRS. (Schwartz''s Ch. 3)'),
    (v_topic_id, '20: What is the most rapid way to "stabilize the cardiac membrane" in a patient with severe hyperkalemia?', '["Insulin + Glucose", "Sodium Bicarbonate", "Calcium Gluconate or Calcium Chloride", "Albuterol"]', 2, 'Calcium antagonizes the effects of K on the heart. (de Virgilio Ch. 2)'),
    (v_topic_id, '21: "Hypokalemia" in a surgical patient often follows which condition?', '["Metabolic Acidosis", "NG tube suctioning / Gastric losses", "Renal failure", "None"]', 1, 'Loss of HCl and K in stomach fluid. (Mont Reid Ch. 2)'),
    (v_topic_id, '22: "Hypomagnesemia" should be suspected in a patient with "refractory":', '["Hyponatremia", "Hypokalemia", "Hypercalcemia", "None"]', 1, 'Magnesium is a cofactor for K reabsorption in the kidney. (Schwartz''s Ch. 3)'),
    (v_topic_id, '23: "Metabolic Alkalosis" with low urine chloride (< 10 mEq/L) is typically "responsive" to:', '["Potassium", "Saline (NaCl)", "Bicarbonate", "None"]', 1, 'Volume depletion is the primary driver. (de Virgilio Ch. 2)'),
    (v_topic_id, '24: A "wide anion gap" metabolic acidosis (MUDPILES) includes which of the following?', '["Diarrhea", "Lactic Acidosis", "Renal Tubular Acidosis", "None"]', 1, 'Common in shock and sepsis. (Mont Reid Ch. 2)'),
    (v_topic_id, '25: What is the maintenance fluid rate for a 70 kg adult using the 4-2-1 rule?', '["70 mL/hr", "110 mL/hr", "150 mL/hr", "200 mL/hr"]', 1, '40 + 20 + 50 = 110 mL/hr. (Schwartz''s Ch. 3)'),

    -- SECTION 3: Hemostasis, Bleeding, and Transfusion
    (v_topic_id, '26: Which clotting factor has the SHORTEST half-life?', '["Factor II", "Factor VII", "Factor IX", "Factor X"]', 1, 'Factor VII is the first to drop in Vitamin K deficiency. (Schwartz''s Ch. 4)'),
    (v_topic_id, '27: "Prothrombin Time" (PT/INR) primarily evaluates which pathway?', '["Intrinsic", "Extrinsic (and common)", "Fibrinolysis", "None"]', 1, 'Evalutes Factors VII, X, V, II, and I. (de Virgilio Ch. 3)'),
    (v_topic_id, '28: "Activated Partial Thromboplastin Time" (aPTT) monitors which drug therapy?', '["Warfarin", "Unfractionated Heparin", "Aspirin", "None"]', 1, 'Monitors the intrinsic pathway. (Mont Reid Ch. 4)'),
    (v_topic_id, '29: What is the most common "inherited" bleeding disorder?', '["Hemophilia A", "von Willebrand Disease", "Factor V Leiden", "Hemophilia B"]', 1, 'Causes defect in platelet adhesion and Factor VIII stability. (Schwartz''s Ch. 4)'),
    (v_topic_id, '30: A patient with "Hemophilia A" is deficient in which factor?', '["Factor VII", "Factor VIII", "Factor IX", "Factor XI"]', 1, 'Classic X-linked recessive disorder. (de Virgilio Ch. 3)'),
    (v_topic_id, '31: "Desmopressin" (DDAVP) is useful in von Willebrand Disease Type 1 because it:', '["Inhibits platelets", "Releases stored vWF from endothelial cells", "Increases Factor VII", "None"]', 1, 'Temporarily boosts vWF and Factor VIII levels. (Mont Reid Ch. 4)'),
    (v_topic_id, '32: What is the most common cause of "postoperative bleeding" in a patient without a known bleeding disorder?', '["DIC", "Inadequate surgical hemostasis", "Factor deficiency", "None"]', 1, 'Usually a technical issue requiring re-exploration. (Schwartz''s Ch. 4)'),
    (v_topic_id, '33: "Massive Transfusion" is defined as replacement of the patient''s entire blood volume within:', '["4 hours", "24 hours", "7 days", "None"]', 1, 'Or 10 units of PRBCs in 24 hours. (de Virgilio Ch. 3)'),
    (v_topic_id, '34: What is the primary risk of "lethargy and tingling" in a patient receiving multiple units of PRBCs?', '["Hypercalcemia", "Hypocalcemia (Citrate toxicity)", "Hypernatremia", "None"]', 1, 'Citrate in blood bags chelates calcium. (Mont Reid Ch. 4)'),
    (v_topic_id, '35: What is the "universal donor" for Fresh Frozen Plasma (FFP)?', '["Type O", "Type AB", "Type A", "Type B"]', 1, 'AB plasma lacks anti-A and anti-B antibodies. (Schwartz''s Ch. 4)'),
    (v_topic_id, '36: One unit of PRBCs is expected to raise the hemoglobin by ____ g/dL in an average adult.', '["0.5", "1.0", "2.0", "3.0"]', 1, 'Corresponding to a 3% rise in hematocrit. (de Virgilio Ch. 3)'),
    (v_topic_id, '37: "TRALI" (Transfusion-Related Acute Lung Injury) is characterized by:', '["High CVP", "Non-cardiogenic pulmonary edema", "Hives", "Fever only"]', 1, 'Most common cause of transfusion-related death. (Mont Reid Ch. 4)'),
    (v_topic_id, '38: A "Febrile Non-hemolytic Transfusion Reaction" is caused by cytokines from:', '["Red cells", "Donor leukocytes", "Platelets", "None"]', 1, 'Prevented by leukoreduction. (Schwartz''s Ch. 4)'),
    (v_topic_id, '39: "Cryoprecipitate" is specifically rich in which factors?', '["II, VII, IX, X", "Fibrinogen, vWF, Factor VIII, and Factor XIII", "Antithrombin III", "None"]', 1, 'Used for hypofibrinogenemia. (de Virgilio Ch. 3)'),
    (v_topic_id, '40: Which medication can REVERSE the effects of Heparin?', '["Vitamin K", "Protamine Sulfate", "FFP", "None"]', 1, 'Binds and neutralizes heparin molecules. (Mont Reid Ch. 4)'),

    -- SECTION 4: Shock
    (v_topic_id, '41: What is the hallmark of "Distributive Shock" (e.g., Sepsis)?', '["Increased CVP", "Decreased Systemic Vascular Resistance (SVR)", "Decreased Cardiac Output", "None"]', 1, 'Vasodilation leads to "warm" shock. (Schwartz''s Ch. 5)'),
    (v_topic_id, '42: "Hypovolemic Shock" is characterized by low cardiac output and ____ SVR.', '["Low", "High", "Normal", "None"]', 1, 'Body compensates with vasoconstriction to maintain BP. (de Virgilio Ch. 5)'),
    (v_topic_id, '43: In "Neurogenic Shock" (spinal cord injury), the patient is unique for having hypotension and:', '["Tachycardia", "Bradycardia", "Fever", "None"]', 1, 'Loss of sympathetic tone prevents compensatory tachycardia. (Mont Reid Ch. 3)'),
    (v_topic_id, '44: What is the most sensitive early sign of "Hemorrhagic Shock"?', '["Hypotension", "Tachycardia", "Altered mental status", "Low urine output"]', 1, 'BP is often maintained until ~30% volume loss. (Schwartz''s Ch. 5)'),
    (v_topic_id, '45: "Septic Shock" is defined as sepsis requiring ____ to maintain MAP >= 65 mmHg.', '["Fluids only", "Vasopressors", "Antibiotics", "None"]', 1, 'And lactate > 2 mmol/L. (de Virgilio Ch. 5)'),
    (v_topic_id, '46: Which type of shock shows an INCREASED Mixed Venous Oxygen Saturation (SvO2)?', '["Hypovolemic", "Septic (Distributive)", "Cardiogenic", "None"]', 1, 'Cells cannot extract oxygen due to shunting/dysfunction. (Mont Reid Ch. 3)'),
    (v_topic_id, '47: What is the first-line vasopressor for septic shock?', '["Dopamine", "Norepinephrine", "Epinephrine", "Phenylephrine"]', 1, 'Alpha-1 and Beta-1 activity. (Schwartz''s Ch. 5)'),
    (v_topic_id, '48: "Cardiogenic Shock" after MI shows an INCREASED ____ on hemodynamic monitoring.', '["Cardiac Index", "Pulmonary Capillary Wedge Pressure (PCWP)", "SvO2", "None"]', 1, 'Indicates pump failure and backup into the lungs. (de Virgilio Ch. 5)'),
    (v_topic_id, '49: "Obstructive Shock" from a Tension Pneumothorax is treated first with:', '["Vasopressors", "Needle decompression / Chest tube", "Intubation", "None"]', 1, 'Mechanical obstruction must be relieved. (Mont Reid Ch. 3)'),
    (v_topic_id, '50: "Lactate" levels are a marker of:', '["Liver function", "Anaerobic metabolism and tissue hypoperfusion", "Kidney function", "None"]', 1, 'Used to monitor shock resuscitation. (Schwartz''s Ch. 5)'),

    -- SECTION 5: Surgical Infections and Antibiotics
    (v_topic_id, '51: A "Clean" surgical wound (e.g., hernia repair) carries an expected infection rate of:', '["< 2%", "5%", "15%", "25%"]', 0, 'Involves no entry into resp, GI, or GU tracts. (Schwartz''s Ch. 6)'),
    (v_topic_id, '52: A "Clean-Contaminated" wound (e.g., elective cholecystectomy) involves:', '["No entry into viscera", "Controlled entry into a hollow viscus", "Gross spillage", "Existing infection"]', 1, 'Includes minor break in technique. (de Virgilio Ch. 6)'),
    (v_topic_id, '53: "Prophylactic" antibiotics should be administered within ____ of the surgical incision.', '["24 hours", "1 hour", "3 hours", "6 hours"]', 1, 'To ensure peak tissue levels at the time of cut. (Mont Reid Ch. 5)'),
    (v_topic_id, '54: For a routine clean case (e.g., mesh hernia), what is the antibiotic of choice?', '["Vancomycin", "Cefazolin (1st Gen Cephalosporin)", "Ciprofloxacin", "Metronidazole"]', 1, 'Covers skin flora like Staph. (Schwartz''s Ch. 6)'),
    (v_topic_id, '55: "Necrotizing Fasciitis" is a surgical emergency requiring immediate:', '["IV Antibiotics only", "Aggressive surgical debridement", "Topical creams", "Watchful waiting"]', 1, 'Antibiotics alone cannot reach necrotic tissue. (de Virgilio Ch. 6)'),
    (v_topic_id, '56: What is the "Classic" organism causing Crepitus (gas in tissues) in gas gangrene?', '["S. aureus", "Clostridium perfringens", "E. coli", "Bacteroides"]', 1, 'Anaerobic spore-forming rods. (Mont Reid Ch. 5)'),
    (v_topic_id, '57: "Surgical Site Infection" (SSI) typically occurs within ____ days of surgery.', '["1-2", "30", "90", "None"]', 1, '90 days if an implant is used. (Schwartz''s Ch. 6)'),
    (v_topic_id, '58: "Deep SSI" involves which layer?', '["Skin and subcutaneous only", "Fascia and muscle layers", "Organs", "None"]', 1, 'Superficial only involves skin. (de Virgilio Ch. 6)'),
    (v_topic_id, '59: Which infection is most common in the first 24-48 hours after surgery?', '["Wound infection", "Clostridial or Group A Strep necrotizing infection", "Abscess", "None"]', 1, 'Most SSIs take 5-7 days to appear. (Mont Reid Ch. 5)'),
    (v_topic_id, '60: "Clostridioides difficile" infection in surgical patients is primarily associated with:', '["Raw food", "Broad-spectrum antibiotic use", "Poor hygiene", "None"]', 1, 'Disruption of gut flora. (Schwartz''s Ch. 6)'),

    -- SECTION 6: Trauma (ATLS Principles)
    (v_topic_id, '61: In the "Primary Survey" of trauma, "A" stands for Airway and:', '["Auscultation", "Anesthesia", "Cervical Spine protection", "None"]', 2, 'Airway is not safe without spine stabilization. (Schwartz''s Ch. 7)'),
    (v_topic_id, '62: "B" in the Primary Survey evaluates Breathing. Which condition must be excluded first?', '["Pneumonia", "Tension Pneumothorax", "Asthma", "None"]', 1, 'Immediate threat to life. (de Virgilio Ch. 4)'),
    (v_topic_id, '63: "C" stands for Circulation. What is the first-line intervention for external bleeding?', '["Tourniquet", "Direct pressure", "IV fluids", "None"]', 1, 'Simple and effective. (Mont Reid Ch. 3)'),
    (v_topic_id, '64: What is the preferred site for "Emergent Needle Decompression" in a child?', '["2nd Intercostal space, mid-clavicular line", "5th Intercostal space, mid-axillary line", "Abdomen", "None"]', 0, 'Adults now shifted to 5th ICS in some protocols, but 2nd is classic. (Schwartz''s Ch. 7)'),
    (v_topic_id, '65: A "Beck''s Triad" (Hypotension, Muffled heart sounds, JVD) indicates:', '["Tension pneumothorax", "Cardiac Tamponade", "Hemothorax", "None"]', 1, 'Treated with pericardiocentesis or window. (de Virgilio Ch. 4)'),
    (v_topic_id, '66: What is the "FAST" exam used for in trauma?', '["Bone fractures", "Detecting free intraperitoneal/pericardial fluid", "Head injury", "None"]', 1, 'Focused Assessment with Sonography for Trauma. (Mont Reid Ch. 3)'),
    (v_topic_id, '67: Which trauma patient should go STRAIGHT to the OR for laparotomy?', '["Stable patient with positive FAST", "Unstable patient with positive FAST", "Stable patient with CT findings", "None"]', 1, 'Hypotension + free fluid = hemorrhage requiring control. (Schwartz''s Ch. 7)'),
    (v_topic_id, '68: "Diagnostic Peritoneal Lavage" (DPL) is considered positive if ____ RBCs/mm3 are found in blunt trauma.', '["1,000", "10,000", "100,000", "None"]', 2, 'Used when FAST is unavailable or inconclusive in unstable patients. (de Virgilio Ch. 4)'),
    (v_topic_id, '69: A "Flail Chest" is defined as ____ or more ribs broken in ____ or more places.', '["1; 1", "2; 2", "3; 2", "None"]', 2, 'Causes paradoxical chest wall movement. (Mont Reid Ch. 3)'),
    (v_topic_id, '70: What is the most common cause of "Delayed" trauma death (days to weeks)?', '["Hemorrhage", "Brain injury", "Sepsis and Multi-organ failure", "None"]', 2, 'Trimodel distribution of death. (Schwartz''s Ch. 7)'),

    -- SECTION 7: Burns
    (v_topic_id, '71: "First-degree Burns" (e.g., sunburn) involve which layer?', '["Epidermis only", "Dermis", "Muscle", "None"]', 0, 'Characterized by erythema and pain without blisters. (Schwartz''s Ch. 8)'),
    (v_topic_id, '72: "Second-degree Burns" (Partial Thickness) are unique for having:', '["Charring", "Blisters", "No pain", "None"]', 1, 'Involve the epidermis and part of the dermis. (de Virgilio Ch. 12)'),
    (v_topic_id, '73: "Third-degree Burns" (Full Thickness) are characterized by:', '["Severe pain", "Leathery, waxy, non-blanching skin (Painless)", "Redness", "None"]', 1, 'Destroys nerve endings. (Mont Reid Ch. 6)'),
    (v_topic_id, '74: According to the "Rule of Nines," what percentage is the entire head of an adult?', '["4.5%", "9%", "18%", "1%"]', 1, 'Arms are 9% each, legs are 18% each. (Schwartz''s Ch. 8)'),
    (v_topic_id, '75: What is the "Parkland Formula" for fluid resuscitation in burns?', '["2 mL x kg x %TBSA", "4 mL x kg x %TBSA", "10 mL x kg x %TBSA", "None"]', 1, 'Half given in first 8 hours. (de Virgilio Ch. 12)'),
    (v_topic_id, '76: Which fluid is preferred for burn resuscitation?', '["D5W", "Lactated Ringer''s", "Normal Saline", "Albumin"]', 1, 'Isotonic and avoids hyperchloremic acidosis. (Mont Reid Ch. 6)'),
    (v_topic_id, '77: "Carbon Monoxide" poisoning should be suspected in house fire victims. What is the treatment?', '["Intubation only", "100% Oxygen", "Antibiotics", "None"]', 1, 'Reduces the half-life of CO-hemoglobin. (Schwartz''s Ch. 8)'),
    (v_topic_id, '78: "Curling''s Ulcer" is a stress ulcer of the stomach/duodenum seen in:', '["Head injury", "Severe burn patients", "Liver failure", "None"]', 1, 'Cushing''s ulcer is seen in head injury. (de Virgilio Ch. 12)'),
    (v_topic_id, '79: "Escharotomy" is indicated in circumferential burns when:', '["Pain is severe", "Distal pulses are absent or compartment pressure > 30", "Fever occurs", "None"]', 1, 'Relieves mechanical restriction to blood flow. (Mont Reid Ch. 6)'),
    (v_topic_id, '80: What is the leading cause of "early" death in burn patients?', '["Infection", "Inhalation injury / Airway compromise", "Renal failure", "None"]', 1, 'Sepsis is the leading cause of late death. (Schwartz''s Ch. 8)'),

    -- SECTION 8: Wound Healing and Care
    (v_topic_id, '81: What are the three phases of wound healing in order?', '["Inflammation, Maturation, Proliferation", "Inflammation, Proliferation, Maturation", "Proliferation, Maturation, Inflammation", "None"]', 1, 'Inflammation starts immediately. (Schwartz''s Ch. 9)'),
    (v_topic_id, '82: Which cell type is the "conductor" of the wound healing orchestra?', '["Neutrophil", "Macrophage", "Fibroblast", "Keratinocyte"]', 1, 'Essential for the transition to proliferation. (de Virgilio Ch. 7)'),
    (v_topic_id, '83: "Proliferation Phase" is characterized by the production of:', '["Vitamin K", "Collagen (Type III initially)", "Melanin", "None"]', 1, 'Fibroblasts are the key cells here. (Mont Reid Ch. 1)'),
    (v_topic_id, '84: "Maturation Phase" (Remodeling) can last up to:', '["1 week", "1 month", "1 year", "None"]', 2, 'Collagen III is replaced by stronger Collagen I. (Schwartz''s Ch. 9)'),
    (v_topic_id, '85: A healed wound never regains more than ____% of its original strength.', '["50%", "80%", "100%", "None"]', 1, 'Scar tissue is less elastic/strong than original tissue. (de Virgilio Ch. 7)'),
    (v_topic_id, '86: "Primary Intention" healing refers to:', '["Leaving the wound open", "Surgical closure (sutures/staples)", "Healing by granulation", "None"]', 1, 'Fastest and most aesthetic. (Mont Reid Ch. 1)'),
    (v_topic_id, '87: "Secondary Intention" healing involves:', '["Immediate closure", "Leaving the wound open to close on its own", "Delayed closure", "None"]', 1, 'Used for contaminated or infected wounds. (Schwartz''s Ch. 9)'),
    (v_topic_id, '88: Which vitamin is essential for collagen cross-linking (Hydroxylation of proline)?', '["Vitamin A", "Vitamin C", "Vitamin D", "Vitamin E"]', 1, 'Deficiency causes Scurvy and poor healing. (de Virgilio Ch. 7)'),
    (v_topic_id, '89: "Keloids" differ from Hypertrophic scars because they:', '["Stay within the wound borders", "Grow beyond the original wound borders", "Are painful", "None"]', 1, 'Common in darker skin types. (Mont Reid Ch. 1)'),
    (v_topic_id, '90: Which medication class significantly impairs wound healing?', '["NSAIDs", "Glucocorticoids (Steroids)", "Antibiotics", "None"]', 1, 'Inhibits the inflammatory phase and fibroblasts. (Schwartz''s Ch. 9)'),

    -- SECTION 9: Surgical Nutrition
    (v_topic_id, '91: "Enteral Nutrition" (Tube feeding) is preferred over Parenteral (IV) because it:', '["Is cheaper", "Maintains gut barrier and prevents bacterial translocation", "Is easier to dose", "None"]', 1, '"If the gut works, use it." (Schwartz''s Ch. 2)'),
    (v_topic_id, '92: "Refeeding Syndrome" is characterized by severe drops in which electrolytes?', '["Sodium", "Phosphate, Magnesium, and Potassium", "Calcium", "None"]', 1, 'Insulin surge causes intracellular shift. (de Virgilio Ch. 7)'),
    (v_topic_id, '93: What is the most common complication of "Total Parenteral Nutrition" (TPN)?', '["Liver failure", "Line-associated sepsis", "Diarrhea", "None"]', 1, 'Hyperglycemia is also very common. (Mont Reid Ch. 1)'),
    (v_topic_id, '94: A patient in a "Hypermetabolic" state (major trauma/burn) requires how many kcal/kg/day?', '["15", "25-35", "50+", "None"]', 1, 'Energy requirements scale with stress. (Schwartz''s Ch. 2)'),
    (v_topic_id, '95: Which amino acid is the primary fuel for enterocytes and is often "conditionally essential" in surgery?', '["Leucine", "Glutamine", "Arginine", "Glycine"]', 1, 'Helps maintain gut integrity. (de Virgilio Ch. 7)'),
    (v_topic_id, '96: "Marasmus" is a form of malnutrition characterized by:', '["Protein deficiency with adequate calories", "Deficiency of both protein and total calories", "Vitamin deficiency only", "None"]', 1, 'Presents as "wasting." (Mont Reid Ch. 1)'),
    (v_topic_id, '97: "Kwashiorkor" is characterized by protein deficiency and leads to:', E'["Extreme thinness", "Edema and \\"potbelly\\" appearance", "Fever", "None"]', 1, 'Albumin levels are very low. (Schwartz''s Ch. 2)'),
    (v_topic_id, '98: How many days of "nothing by mouth" (NPO) can a well-nourished adult tolerate before requiring nutritional support?', '["1 day", "3 days", "7-10 days", "None"]', 2, 'Support started earlier in malnourished patients. (de Virgilio Ch. 7)'),
    (v_topic_id, '99: Which mineral is essential for wound healing and is a cofactor for many enzymes?', '["Iron", "Zinc", "Copper", "Selenium"]', 1, 'Deficiency causes perioral rash and poor healing. (Mont Reid Ch. 1)'),
    (v_topic_id, '100: TPN through a "peripheral" line (PPN) is limited by:', '["Cost", "Osmolarity (must be < 900 mOsm/L)", "Volume", "None"]', 1, 'Hypertonic TPN requires a central line. (Schwartz''s Ch. 2)');

    -- Batch 2: 101-200 (Oncology, Post-op, Technique)

    -- Batch 3: 201-320 (Specific Pearls and Advanced Topics)

END $$;

COMMIT;
